import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  TextField,
  Typography,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  IconButton,
  Alert,
  Snackbar,
} from '@mui/material';
import { Delete as DeleteIcon, Edit as EditIcon, CloudUpload as CloudUploadIcon, ArrowUpward as ArrowUpwardIcon, ArrowDownward as ArrowDownwardIcon } from '@mui/icons-material';
import { collection, addDoc, getDocs, doc, updateDoc, deleteDoc, query, orderBy, writeBatch } from 'firebase/firestore';
import { db } from '../firebase';
import { Category, MenuItem as FoodItem } from '../types';
import { categories as initialCategories } from '../categories';
import { foodItems as initialFoodItems } from '../foodItems';

const MenuItems: React.FC = () => {
  const [items, setItems] = useState<FoodItem[]>([]);
  const [categoriesList, setCategories] = useState<Category[]>([]);
  const [open, setOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState<FoodItem | null>(null);
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' as 'success' | 'error' });
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: '',
    categoryId: '',
    imagePath: '',
  });

  useEffect(() => {
    fetchItems();
    fetchCategories();
  }, []);

  const fetchItems = async () => {
    const q = query(collection(db, 'menuItems'), orderBy('sortOrder', 'asc'));
    const querySnapshot = await getDocs(q);
    const itemsData = querySnapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data()
    })) as FoodItem[];
    setItems(itemsData);
  };

  const fetchCategories = async () => {
    const q = query(collection(db, 'categories'), orderBy('sortOrder', 'asc'));
    const querySnapshot = await getDocs(q);
    const categoriesData = querySnapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data()
    })) as Category[];
    setCategories(categoriesData);
  };

  const handleOpen = (item?: FoodItem) => {
    if (item) {
      setSelectedItem(item);
      setFormData({
        name: item.name,
        description: item.description,
        price: item.price.toString(),
        categoryId: item.categoryId,
        imagePath: item.imagePath || '',
      });
    } else {
      setSelectedItem(null);
      setFormData({
        name: '',
        description: '',
        price: '',
        categoryId: '',
        imagePath: '',
      });
    }
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    setSelectedItem(null);
    setFormData({
      name: '',
      description: '',
      price: '',
      categoryId: '',
      imagePath: '',
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const itemData = {
      name: formData.name,
      description: formData.description,
      price: parseFloat(formData.price),
      categoryId: formData.categoryId,
      imagePath: formData.imagePath,
    };

    try {
      if (selectedItem) {
        await updateDoc(doc(db, 'menuItems', selectedItem.id), itemData);
        setSnackbar({
          open: true,
          message: 'مورد منو با موفقیت ویرایش شد',
          severity: 'success'
        });
      } else {
        const newSortOrder = items.length > 0 ? Math.max(...items.map(i => i.sortOrder || 0)) + 1 : 0;
        await addDoc(collection(db, 'menuItems'), { ...itemData, sortOrder: newSortOrder });
        setSnackbar({
          open: true,
          message: 'مورد منوی جدید با موفقیت اضافه شد',
          severity: 'success'
        });
      }
      handleClose();
      fetchItems();
    } catch (error) {
      console.error('Error saving menu item:', error);
      setSnackbar({
        open: true,
        message: 'خطا در ذخیره مورد منو',
        severity: 'error'
      });
    }
  };

  const handleDelete = async (id: string) => {
    if (window.confirm('آیا از حذف این مورد اطمینان دارید؟')) {
      try {
        await deleteDoc(doc(db, 'menuItems', id));
        setSnackbar({
          open: true,
          message: 'مورد منو با موفقیت حذف شد',
          severity: 'success'
        });
        fetchItems();
      } catch (error) {
        console.error('Error deleting menu item:', error);
        setSnackbar({
          open: true,
          message: 'خطا در حذف مورد منو',
          severity: 'error'
        });
      }
    }
  };

  const moveMenuItem = async (itemId: string, direction: 'up' | 'down') => {
    const itemIndex = items.findIndex(item => item.id === itemId);
    if (itemIndex === -1) return;

    const newItems = [...items];
    const [movedItem] = newItems.splice(itemIndex, 1);

    let newIndex;
    if (direction === 'up') {
      newIndex = Math.max(0, itemIndex - 1);
    } else {
      newIndex = Math.min(newItems.length, itemIndex + 1);
    }

    newItems.splice(newIndex, 0, movedItem);

    const updates = newItems.map(async (item, index) => {
      const newSortOrder = index;
      if (item.sortOrder !== newSortOrder) {
        await updateDoc(doc(db, 'menuItems', item.id), { sortOrder: newSortOrder });
      }
    });

    try {
      await Promise.all(updates);
      setSnackbar({
        open: true,
        message: 'ترتیب مورد منو با موفقیت تغییر یافت',
        severity: 'success'
      });
      fetchItems();
    } catch (error) {
      console.error('Error reordering menu item:', error);
      setSnackbar({
        open: true,
        message: 'خطا در تغییر ترتیب مورد منو',
        severity: 'error'
      });
    }
  };

  const handleImportData = async () => {
    try {
      const batch = writeBatch(db);

      for (const category of initialCategories) {
        const categoryRef = doc(collection(db, 'categories'));
        batch.set(categoryRef, {
          name: category.name,
          icon: category.icon,
          sortOrder: categoriesList.length + initialCategories.indexOf(category)
        });
      }

      for (const item of initialFoodItems) {
        const itemRef = doc(collection(db, 'menuItems'));
        batch.set(itemRef, {
          name: item.name,
          description: item.description,
          price: item.price,
          categoryId: item.category,
          imagePath: item.imagePath || '',
          sortOrder: items.length + initialFoodItems.indexOf(item)
        });
      }

      await batch.commit();
      setSnackbar({
        open: true,
        message: 'داده‌ها با موفقیت وارد شدند',
        severity: 'success'
      });

      fetchItems();
      fetchCategories();
    } catch (error) {
      console.error('Error importing data:', error);
      setSnackbar({
        open: true,
        message: 'خطا در وارد کردن داده‌ها',
        severity: 'error'
      });
    }
  };

  const handleCloseSnackbar = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
        <Typography variant="h4" component="h1">
          موارد منو
        </Typography>
        <Box sx={{ display: 'flex', gap: 2 }}>
          <Button
            variant="outlined"
            color="primary"
            startIcon={<CloudUploadIcon />}
            onClick={handleImportData}
          >
            وارد کردن داده‌های اولیه
          </Button>
          <Button variant="contained" color="primary" onClick={() => handleOpen()}>
            افزودن مورد جدید
          </Button>
        </Box>
      </Box>

      {categoriesList.map((category) => {
        const categoryItems = items.filter(item => item.categoryId === category.id).sort((a, b) => a.sortOrder - b.sortOrder);
        if (categoryItems.length === 0) return null;

        return (
          <Card key={category.id} sx={{ mb: 4 }}>
            <CardContent>
              <Typography variant="h5" component="h2" sx={{ mb: 2 }}>{category.name}</Typography>
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2 }}>
                {categoryItems.map((item, index) => (
                  <Card key={item.id} sx={{ width: 200, display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
                    <CardContent>
                      <Typography variant="h6" component="div" sx={{ mb: 1 }}>{item.name}</Typography>
                      <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>{item.description}</Typography>
                      <Typography variant="subtitle1" color="primary.main">{item.price} تومان</Typography>
                    </CardContent>
                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', p: 1 }}>
                      <IconButton onClick={() => handleOpen(item)} size="small">
                        <EditIcon />
                      </IconButton>
                      <IconButton onClick={() => handleDelete(item.id)} size="small" color="error">
                        <DeleteIcon />
                      </IconButton>
                      <IconButton 
                        onClick={() => moveMenuItem(item.id, 'up')}
                        size="small"
                        disabled={index === 0}
                      >
                        <ArrowUpwardIcon />
                      </IconButton>
                      <IconButton 
                        onClick={() => moveMenuItem(item.id, 'down')}
                        size="small"
                        disabled={index === categoryItems.length - 1}
                      >
                        <ArrowDownwardIcon />
                      </IconButton>
                    </Box>
                  </Card>
                ))}
              </Box>
            </CardContent>
          </Card>
        );
      })}

      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>
          {selectedItem ? 'ویرایش مورد منو' : 'افزودن مورد جدید'}
        </DialogTitle>
        <form onSubmit={handleSubmit}>
          <DialogContent>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
              <TextField
                fullWidth
                label="نام"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                required
              />
              <TextField
                fullWidth
                label="توضیحات"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              />
              <TextField
                fullWidth
                label="قیمت"
                value={formData.price}
                onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                type="number"
                required
              />
              <FormControl fullWidth required>
                <InputLabel>دسته‌بندی</InputLabel>
                <Select
                  value={formData.categoryId}
                  label="دسته‌بندی"
                  onChange={(e) => setFormData({ ...formData, categoryId: e.target.value as string })}
                >
                  {categoriesList.map((category) => (
                    <MenuItem key={category.id} value={category.id}>
                      {category.name}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <TextField
                fullWidth
                label="مسیر عکس"
                value={formData.imagePath}
                onChange={(e) => setFormData({ ...formData, imagePath: e.target.value })}
                helperText="URL یا مسیر فایل"
              />
            </Box>
          </DialogContent>
          <DialogActions>
            <Button onClick={handleClose}>انصراف</Button>
            <Button type="submit" variant="contained" color="primary">
              {selectedItem ? 'ذخیره تغییرات' : 'افزودن'}
            </Button>
          </DialogActions>
        </form>
      </Dialog>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default MenuItems;
